1	// Shared motion language. The overshoot easing is the terminal's signature
2	// "bounce/pop-in" feel (cubic-bezier(0.34,1.56,0.64,1)).
3	export const OVERSHOOT = [0.34, 1.56, 0.64, 1] as const;
4	export const POP_DURATION = 0.42;
5	export const STAGGER_STEP = 0.06;
6	
7	/** Framer Motion transition for a pop-in, staggered by sibling index. */
8	export function popInTransition(index = 0) {
9	  return { duration: POP_DURATION, ease: OVERSHOOT, delay: index * STAGGER_STEP };
10	}
11	
12	/** True when the user has asked for reduced motion. SSR/test-safe. */
13	export function prefersReducedMotion(): boolean {
14	  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
15	  return window.matchMedia("(prefers-reduced-motion: reduce)").matches === true;
16	}
