2	import { motion } from "framer-motion";
3	import { CSSProperties, ReactNode } from "react";
4	import { OVERSHOOT, POP_DURATION, STAGGER_STEP, prefersReducedMotion } from "@/lib/motion";
5	
6	/**
7	 * Wraps content in the signature bounce/pop-in entrance. Pass `index` to stagger
8	 * siblings. Honours prefers-reduced-motion with a plain fade (no transform).
9	 */
10	export function PopIn({
11	  children, index = 0, className, style,
12	}: { children: ReactNode; index?: number; className?: string; style?: CSSProperties }) {
13	  const reduced = prefersReducedMotion();
14	  return (
15	    <motion.div
16	      className={className}
17	      style={style}
18	      initial={reduced ? { opacity: 0 } : { opacity: 0, y: 12, scale: 0.97 }}
19	      animate={reduced ? { opacity: 1 } : { opacity: 1, y: 0, scale: 1 }}
20	      transition={reduced
21	        ? { duration: 0.2, ease: "easeOut", delay: index * 0.03 }
22	        : { duration: POP_DURATION, ease: OVERSHOOT, delay: index * STAGGER_STEP }}
23	    >
24	      {children}
25	    </motion.div>
26	  );
27	}
