6	/** Fires a compact "payment received" toast + chime when a transaction completes. */
7	export function usePaymentReceivedToast() {
8	  const { addNotification } = useNotifications();
9	  const seen = useRef<Set<string>>(new Set());
10	
11	  useEffect(() => {
12	    const handler = (message: any) => {
13	      const tx = message?.transaction;
14	      if (!tx || tx.status !== "completed") return;
15	      const key = `${tx.id}:${tx.completedSplits ?? 0}`;
16	      if (seen.current.has(key)) return;
17	      seen.current.add(key);
18	
19	      // The transactions table stores the dollar value in `price` (decimal string),
20	      // not a cents field — see shared/schema.ts. Prefer that; keep cents fallbacks.
21	      let amount: string;
22	      if (tx.price != null) {
23	        amount = "$" + parseFloat(tx.price).toLocaleString("en-NZ", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
24	      } else {
25	        const cents = tx.amountReceivedCents ?? tx.amountCents ?? tx.totalCents ?? 0;
26	        amount = "$" + (cents / 100).toLocaleString("en-NZ", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
27	      }
28	      addNotification({ type: "success", title: "Payment received", message: "", amount, compact: true, duration: 3500 } as any);
29	      playPaymentChime();
30	    };
31	    sseClient.subscribe("transaction_updated", handler);
32	    return () => sseClient.unsubscribe("transaction_updated", handler);
33	  }, [addNotification]);
34	}
