+jest.mock("../storage", () => ({
+  storage: {
+    getInvoiceRentRequest: jest.fn(),
+    updateInvoiceRentRequest: jest.fn(async (_id: string, p: any) => ({ id: _id, ...p })),
+    logTransactionEvent: jest.fn(),
+  },
+}));
+
+import { storage } from "../storage";
+import { sendInvoiceReminder } from "../property-cron";
+
+const now = new Date("2026-06-15T10:00:00Z");
+
+it("rejects a paid invoice", async () => {
+  (storage.getInvoiceRentRequest as jest.Mock).mockResolvedValue({ id: "i1", status: "paid" });
+  const r = await sendInvoiceReminder("i1", "http://x", now);
+  expect(r).toMatchObject({ ok: false, reason: "not_payable" });
+});
+
+it("rejects within the 5-minute cooldown", async () => {
+  (storage.getInvoiceRentRequest as jest.Mock).mockResolvedValue({
+    id: "i1", status: "overdue", lastReminderSentAt: new Date("2026-06-15T09:58:00Z"),
+  });
+  const r = await sendInvoiceReminder("i1", "http://x", now);
+  expect(r.ok).toBe(false);
+  expect(r.reason).toBe("cooldown");
+  expect(r.retryAfterMs).toBeGreaterThan(0);
+});

